#!/usr/bin/python3
from pwn import *
import re
import time

def detect_encryption_mode(ciphertext, block_size=16):
    blocks = [ciphertext[i:i+block_size] for i in range(0, len(ciphertext), block_size)]
    seen_blocks = set()
    repeated_blocks = 0

    for block in blocks:
        if block in seen_blocks:
            repeated_blocks += 1
        seen_blocks.add(block)

    return "ECB" if repeated_blocks > 0 else "CBC"

def main():
    while True:
        try:
            conn = remote('crypto.chal.csaw.io', 8000)

            # Get initial prompt
            resp = conn.recvuntil(b'Enter plaintext:', timeout=2).decode()
            print(resp)

            while True:
                # Send plaintext
                conn.sendline(b'A' * 64)
                time.sleep(0.1)  # Small delay to ensure server processes

                # Get response until we see the next prompt or "flag{"
                response = ""
                while True:
                    try:
                        chunk = conn.recv(timeout=1).decode()
                        if not chunk:
                            break
                        response += chunk
                        if 'flag{' in response or 'Enter plaintext:' in response:
                            break
                    except:
                        break

                print(response)

                # Check for flag
                if 'flag{' in response:
                    flag = re.search(r'flag{[^}]+}', response).group(0)
                    print(f"\nFound flag: {flag}")
                    return

                # Extract and analyze ciphertext
                hex_match = re.search(r'Ciphertext is:\s*([a-fA-F0-9]+)', response)
                if hex_match:
                    ciphertext = bytes.fromhex(hex_match.group(1))
                    mode = detect_encryption_mode(ciphertext)
                    print(f"Detected mode: {mode}")
                    conn.sendline(mode.encode())
                    time.sleep(0.1)  # Small delay to ensure server processes

        except EOFError:
            print("Connection closed by server - retrying...")
            time.sleep(1)
            continue
        except Exception as e:
            print(f"Error occurred: {e} - retrying...")
            time.sleep(1)
            continue
        finally:
            try:
                conn.close()
            except:
                pass

if __name__ == "__main__":
    main()
